import * as React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import info from "../data/data.json";
import SEO from "../components/seo";
import Layout from "../components/layout";
import ProjectCard from "../components/projectCard";
import type {
  ArchivePortfolioGridProps,
  ArchivePortfolioProject,
} from "../components/archivePortfolioGrid";
import { AuditRequestButton } from "../components/auditRequestModal";
import { trackEvent } from "../utils/analytics";
import {
  featuredCaseStudyKeys,
  mapLiveProjectsWithImages,
  projectRelatedServiceKeys,
  type LivePortfolioProject,
  type LivePortfolioProjectWithImages,
} from "../utils/livePortfolio";

function Section({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <section className="w-full py-14">
      <div className="w-full px-4 sm:px-8 lg:px-12">
        <header className="mb-8">
          <h2 className="text-2xl sm:text-3xl font-semibold tracking-tight text-accent">{title}</h2>
          {subtitle ? <p className="mt-2 max-w-4xl text-base text-neutral">{subtitle}</p> : null}
        </header>
        {children}
      </div>
    </section>
  );
}

function Pill({ children }: { children: React.ReactNode }) {
  return (
    <span className="inline-flex items-center rounded-full border border-neutral/25 bg-primary px-3 py-1 text-xs font-medium text-accent">
      {children}
    </span>
  );
}

function BulletList({ items }: { items: string[] }) {
  return (
    <ul className="mt-4 space-y-2 text-sm text-accent">
      {items.map((item) => (
        <li key={item} className="flex gap-2">
          <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-neutral" />
          <span className="min-w-0">{item}</span>
        </li>
      ))}
    </ul>
  );
}

export default function PortfolioPage() {
  const { t } = useTranslation();
  const { language } = useI18next();
  const [showArchive, setShowArchive] = React.useState(false);
  const [isArchiveLoading, setIsArchiveLoading] = React.useState(false);
  const [ArchivePortfolioGrid, setArchivePortfolioGrid] = React.useState<
    React.ComponentType<ArchivePortfolioGridProps> | null
  >(null);

  const servicesItems = (t("services.items", { returnObjects: true }) as Array<{
    key: string;
    title: string;
    href: string;
  }>) || [];
  const liveProjects = (t("portfolio.live.items", { returnObjects: true }) as LivePortfolioProject[]) || [];
  const archivedProjects = (t("portfolio.archive.items", { returnObjects: true }) as ArchivePortfolioProject[]) || [];
  const liveProjectsWithImages = mapLiveProjectsWithImages(liveProjects) as LivePortfolioProjectWithImages[];
  const featuredProjects = liveProjectsWithImages.filter((project) =>
    featuredCaseStudyKeys.includes(project.imageKey as (typeof featuredCaseStudyKeys)[number])
  );
  const onlineProjects = liveProjectsWithImages.filter(
    (project) => !featuredCaseStudyKeys.includes(project.imageKey as (typeof featuredCaseStudyKeys)[number])
  );

  const preloadArchiveGrid = async () => {
    if (ArchivePortfolioGrid) {
      return;
    }

    try {
      setIsArchiveLoading(true);
      const module = await import("../components/archivePortfolioGrid");
      setArchivePortfolioGrid(() => module.default);
    } finally {
      setIsArchiveLoading(false);
    }
  };

  const handleArchiveToggle = async () => {
    if (showArchive) {
      setShowArchive(false);
      return;
    }

    setShowArchive(true);
    await preloadArchiveGrid();
  };

  return (
    <Layout data={info}>
      <main className="w-full min-h-screen bg-primary text-accent">
        <section className="relative overflow-hidden border-b border-neutral/20 bg-[radial-gradient(circle_at_top_left,_rgba(255,255,255,0.6),_transparent_38%),linear-gradient(135deg,_rgba(255,240,224,0.92),_rgba(249,249,249,0.96))] py-16 sm:py-20">
          <div className="w-full px-4 sm:px-8 lg:px-12">
            <div className="grid gap-8 lg:grid-cols-12">
              <div className="lg:col-span-8">
                <p className="text-xs font-semibold uppercase tracking-[0.18em] text-neutral">
                  {t("portfolioPage.hero.kicker")}
                </p>
                <h1 className="mt-4 max-w-5xl text-3xl font-semibold tracking-tight text-accent sm:text-5xl">
                  {t("portfolioPage.hero.title")}
                </h1>
                <p className="mt-4 max-w-3xl text-base leading-7 text-neutral sm:text-lg">
                  {t("portfolioPage.hero.desc")}
                </p>
                <div className="mt-6 flex flex-wrap gap-2">
                  <Pill>{`${featuredProjects.length} ${t("portfolioPage.hero.counts.featured")}`}</Pill>
                  <Pill>{`${onlineProjects.length} ${t("portfolioPage.hero.counts.online")}`}</Pill>
                  <Pill>{`${archivedProjects.length} ${t("portfolioPage.hero.counts.archived")}`}</Pill>
                </div>
                <div className="mt-8 flex flex-wrap gap-3">
                  <a
                    href="#featured-projects"
                    className="inline-flex items-center rounded-2xl bg-accent px-5 py-3 text-sm font-semibold text-primary hover:opacity-90"
                  >
                    {t("portfolioPage.sections.featured.title")}
                  </a>
                  <AuditRequestButton
                    serviceName={t("contact.auditService") as string}
                    source="portfolio.hero.primary"
                    className="inline-flex items-center rounded-2xl border border-neutral/25 bg-secondary px-5 py-3 text-sm font-semibold text-accent hover:bg-secondary/70"
                  >
                    {t("contact.cta")}
                  </AuditRequestButton>
                </div>
              </div>

              <div className="lg:col-span-4">
                <div className="rounded-2xl border border-neutral/20 bg-secondary/90 p-6 shadow-sm backdrop-blur-[2px]">
                  <p className="text-sm font-semibold text-accent">{t("portfolio.title")}</p>
                  <BulletList items={t("portfolioPage.hero.items", { returnObjects: true }) as string[]} />
                </div>
              </div>
            </div>
          </div>
        </section>

        <Section
          title={t("portfolioPage.sections.featured.title")}
          subtitle={t("portfolioPage.sections.featured.desc") as string}
        >
          <div id="featured-projects" className="space-y-8">
            {featuredProjects.map((project) => {
              const relatedServices = (projectRelatedServiceKeys[project.imageKey] || [])
                .map((serviceKey) => servicesItems.find((item) => item.key === serviceKey))
                .filter((item): item is { key: string; title: string; href: string } => Boolean(item));

              return (
                <article
                  key={project.imageKey}
                  id={project.imageKey}
                  className="overflow-hidden rounded-3xl border border-neutral-200 bg-secondary shadow-sm"
                >
                  <div className="grid gap-0 lg:grid-cols-2">
                    <div className="border-b border-neutral-200 lg:border-b-0 lg:border-r">
                      <img
                        src={project.images.large.src}
                        alt={project.images.large.alt || project.title}
                        className="h-full w-full object-cover"
                        decoding="async"
                        width={1600}
                        height={1000}
                      />
                    </div>

                    <div className="p-6 lg:p-8">
                      <div className="flex flex-wrap items-center gap-4">
                        <img
                          src={project.images.logo.src}
                          alt={project.images.logo.alt || `${project.title} logo`}
                          className="h-12 w-auto"
                          decoding="async"
                          width={240}
                          height={96}
                        />
                        <div>
                          <h2 className="text-2xl font-semibold text-accent">{project.title}</h2>
                          <p className="mt-1 text-sm text-neutral">
                            <span className="font-medium text-accent">{project.role}</span>
                            {" · "}
                            <span>{project.stack}</span>
                          </p>
                        </div>
                      </div>

                      {project.note ? (
                        <p className="mt-5 text-base leading-7 text-neutral">{project.note}</p>
                      ) : null}

                      {project.useCase ? (
                        <section className="mt-6 rounded-2xl border border-neutral/20 bg-primary/60 p-5">
                          <p className="text-xs font-semibold uppercase tracking-[0.18em] text-neutral">
                            {t("selectedProjects.labels.useCase")}
                          </p>
                          <p className="mt-3 text-sm leading-6 text-neutral">
                            {project.useCase.summary}
                          </p>
                          <div className="mt-4 grid gap-3 md:grid-cols-3">
                            <div className="rounded-2xl border border-neutral/20 bg-secondary p-4">
                              <h3 className="text-sm font-semibold text-accent">
                                {t("selectedProjects.labels.challenge")}
                              </h3>
                              <p className="mt-2 text-sm leading-6 text-neutral">{project.useCase.challenge}</p>
                            </div>
                            <div className="rounded-2xl border border-neutral/20 bg-secondary p-4">
                              <h3 className="text-sm font-semibold text-accent">
                                {t("selectedProjects.labels.approach")}
                              </h3>
                              <p className="mt-2 text-sm leading-6 text-neutral">{project.useCase.approach}</p>
                            </div>
                            <div className="rounded-2xl border border-neutral/20 bg-secondary p-4">
                              <h3 className="text-sm font-semibold text-accent">
                                {t("selectedProjects.labels.outcome")}
                              </h3>
                              <p className="mt-2 text-sm leading-6 text-neutral">{project.useCase.outcome}</p>
                            </div>
                          </div>
                        </section>
                      ) : null}

                      <ul className="mt-5 space-y-3 text-sm text-accent">
                        {project.highlights.map((highlight) => (
                          <li key={highlight} className="flex gap-3">
                            <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-neutral" />
                            <span className="min-w-0">{highlight}</span>
                          </li>
                        ))}
                      </ul>

                      {relatedServices.length ? (
                        <div className="mt-6">
                          <p className="text-xs font-semibold uppercase tracking-[0.18em] text-neutral">
                            {t("selectedProjects.labels.relatedServices")}
                          </p>
                          <div className="mt-3 flex flex-wrap gap-2">
                            {relatedServices.map((service) => (
                              <Link
                                key={`${project.imageKey}-${service.key}`}
                                to={service.href}
                                onClick={() =>
                                  trackEvent("service_related_link_click", {
                                    source: "portfolio.featured.relatedServices",
                                    project_name: project.title,
                                    service_key: service.key,
                                  })}
                                className="inline-flex items-center rounded-full border border-neutral/25 bg-primary px-3 py-2 text-xs font-medium text-accent hover:bg-primary/70"
                              >
                                {service.title}
                              </Link>
                            ))}
                          </div>
                        </div>
                      ) : null}

                      <div className="mt-6 flex flex-wrap gap-3">
                        <a
                          href={project.href}
                          target="_blank"
                          rel="noreferrer"
                          onClick={() =>
                            trackEvent("portfolio_click", {
                              source: "portfolio.featured.visit",
                              project_name: project.title,
                              target_url: project.href,
                            })}
                          className="inline-flex items-center rounded-2xl bg-accent px-5 py-3 text-sm font-semibold text-primary hover:opacity-90"
                        >
                          {t("selectedProjects.labels.visitSite")}
                        </a>
                        <Link
                          to={language === "fr" ? "/fr/services/" : "/en/services/"}
                          className="inline-flex items-center rounded-2xl border border-neutral/25 bg-primary px-5 py-3 text-sm font-semibold text-accent hover:bg-primary/70"
                        >
                          {t("selectedProjects.labels.viewAllServices")}
                        </Link>
                      </div>
                    </div>
                  </div>
                </article>
              );
            })}
          </div>
        </Section>

        <Section
          title={t("portfolioPage.sections.live.title")}
          subtitle={t("portfolioPage.sections.live.desc") as string}
        >
          <div className="grid gap-4 lg:grid-cols-4">
            {onlineProjects.map((project) => (
              <div key={project.imageKey} id={project.imageKey}>
                <ProjectCard
                  project={project}
                  detailsLabel={t("portfolio.live.details")}
                  visitLabel={t("portfolio.live.visit")}
                  closeLabel={t("portfolio.live.close")}
                />
              </div>
            ))}
          </div>
        </Section>

        <Section
          title={t("portfolioPage.sections.archive.title")}
          subtitle={t("portfolioPage.sections.archive.desc") as string}
        >
          <div className="rounded-2xl border border-neutral/20 bg-secondary p-5 shadow-sm">
            <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
              <div className="max-w-3xl">
                <p className="text-sm font-medium text-accent">{t("portfolio.archive.note")}</p>
                <p className="mt-2 text-sm text-neutral">{t("portfolio.archive.summary")}</p>
              </div>

              <button
                type="button"
                onClick={() => void handleArchiveToggle()}
                onMouseEnter={() => void preloadArchiveGrid()}
                onFocus={() => void preloadArchiveGrid()}
                className="inline-flex items-center justify-center rounded-2xl border border-neutral/25 bg-primary px-5 py-3 text-sm font-semibold text-accent hover:bg-primary/70"
                aria-expanded={showArchive}
                aria-controls="archived-portfolio-grid"
              >
                {showArchive ? t("portfolio.archive.hide") : t("portfolio.archive.reveal")}
              </button>
            </div>

            {showArchive ? (
              isArchiveLoading || !ArchivePortfolioGrid ? (
                <p className="mt-6 text-sm text-neutral">{t("portfolio.archive.loading")}</p>
              ) : (
                <div id="archived-portfolio-grid">
                  <ArchivePortfolioGrid
                    projects={archivedProjects}
                    openLabel={t("portfolio.archive.cta")}
                    closeLabel={t("portfolio.archive.close")}
                  />
                </div>
              )
            ) : null}
          </div>
        </Section>

        <Section
          title={t("selectedProjects.cta.title")}
          subtitle={t("selectedProjects.cta.desc") as string}
        >
          <div className="rounded-2xl border border-neutral-200 bg-secondary p-6 shadow-sm">
            <div className="flex flex-wrap gap-3">
              <AuditRequestButton
                serviceName={t("contact.auditService") as string}
                source="portfolio.cta.primary"
                className="inline-flex items-center rounded-2xl bg-accent px-5 py-3 text-sm font-semibold text-primary hover:opacity-90"
              >
                {t("selectedProjects.labels.requestAudit")}
              </AuditRequestButton>
              <Link
                to={language === "fr" ? "/fr/services/" : "/en/services/"}
                className="inline-flex items-center rounded-2xl border border-neutral/25 bg-primary px-5 py-3 text-sm font-semibold text-accent hover:bg-primary/70"
              >
                {t("selectedProjects.labels.viewAllServices")}
              </Link>
            </div>
          </div>
        </Section>
      </main>
    </Layout>
  );
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

export const Head: HeadFC = ({ location, pageContext }) => {
  const language = (pageContext as { language?: string }).language || "fr";
  const pathname = language === "fr" ? "/fr/portfolio/" : "/en/portfolio/";
  const alternates = [
    { hrefLang: "fr", href: "https://riano.ca/fr/portfolio/" },
    { hrefLang: "en", href: "https://riano.ca/en/portfolio/" },
    { hrefLang: "x-default", href: "https://riano.ca/fr/portfolio/" },
  ];

  return (
    <SEO
      data={info}
      titleKey="seo.portfolio.metaTitle"
      descriptionKey="seo.portfolio.metaDescription"
      pathname={pathname}
      currentPathname={location.pathname}
      language={language}
      alternates={alternates}
      schemaType="ProfessionalService"
    />
  );
};
